import{_ as s,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"77. 常见的未定义行为","description":"The Little Book of C 中文版 — 77. 常见的未定义行为","frontmatter":{"title":"77. 常见的未定义行为","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","08-调试测试与 profiling","中文"],"description":"The Little Book of C 中文版 — 77. 常见的未定义行为","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":77,"sidebarWeight":77,"alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/077-Common Undefined Behaviors","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/077-Common Undefined Behaviors"},"headers":[],"relativePath":"posts/c教程/zh-CN/08-调试测试与 profiling/077-Common Undefined Behaviors.md","filePath":"posts/c教程/zh-CN/08-调试测试与 profiling/077-Common Undefined Behaviors.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/08-调试测试与 profiling/077-Common Undefined Behaviors.md"};function p(l,a,o,d,c,h){return e(),n("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/08-Debugging Testing Profiling/077-Common Undefined Behaviors)</p><p>C给你自由，但也给你责任。与高级语言不同，C 不能保护您免受危险错误的影响。有些操作会导致未定义的行为 (UB)：允许编译器执行任何响应操作、崩溃、挂起，甚至看起来工作正常，直到实际情况并非如此。</p><p>未定义的行为使得 C 语言既强大又危险。让我们探讨一下它的原因、如何识别它以及如何编写永远不会落入其陷阱的代码。</p><h4 id="步骤-1-什么是未定义行为" tabindex="-1">步骤 1. 什么是未定义行为？ <a class="header-anchor" href="#步骤-1-什么是未定义行为" aria-label="Permalink to &quot;步骤 1. 什么是未定义行为？&quot;">​</a></h4><p>在 C 标准中，未定义的行为意味着“没有规则适用”。如果你的程序执行了语言未定义的操作，编译器可以假设它永远不会发生并自由优化。</p><p>这意味着您的程序可能：</p><ul><li>立即崩溃。</li><li>产生错误的结果。</li><li>每次都有不同的行为。</li><li>在一个编译器上工作正常，在另一个编译器上失败。</li></ul><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 5 / 0;  // UB: division by zero</span></span></code></pre></div><p>编译器不需要警告您或安全地处理这个问题。</p><h4 id="步骤-2-ub-的常见来源" tabindex="-1">步骤 2. UB 的常见来源 <a class="header-anchor" href="#步骤-2-ub-的常见来源" aria-label="Permalink to &quot;步骤 2. UB 的常见来源&quot;">​</a></h4><p>以下是每个 C 程序员必须知道的最常见的错误：</p><table tabindex="0"><thead><tr><th>类别</th><th>示例</th></tr></thead><tbody><tr><td>越界访问</td><td><code>arr[10]</code>当数组有 10 个元素时</td></tr><tr><td>使用未初始化的变量</td><td><code>int x; printf(&quot;%d&quot;, x);</code></td></tr><tr><td>悬空指针访问</td><td>之后使用内存<code>free()</code></td></tr><tr><td>无效的指针算术</td><td><code>(p + 5)</code>什么时候<code>p</code>不指向数组</td></tr><tr><td>有符号整数溢出</td><td><code>int x = INT_MAX + 1;</code></td></tr><tr><td>修改和读取同一变量</td><td><code>i = i++;</code>或者<code>a[i] = i++;</code></td></tr><tr><td>空指针取消引用</td><td><code>int *p = NULL; *p = 5;</code></td></tr><tr><td>错误类型双关语</td><td>通过错误的指针类型以 int 形式访问 float</td></tr><tr><td>不匹配<code>malloc</code>/<code>free</code></td><td><code>free()</code>内存未被分配<code>malloc()</code></td></tr><tr><td>违反<code>const</code>或者<code>volatile</code>合同</td><td>写信给一个<code>const</code>变量</td></tr></tbody></table><h4 id="步骤-3-越界访问" tabindex="-1">步骤 3. 越界访问 <a class="header-anchor" href="#步骤-3-越界访问" aria-label="Permalink to &quot;步骤 3. 越界访问&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int arr[3] = {1, 2, 3};</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, arr[3]);  // UB: index 3 is past the end</span></span></code></pre></div><p>C 不检查边界，你要对此负责。您可能会打印垃圾、崩溃或意外覆盖另一个变量。</p><p>经常检查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (index &gt;= 0 &amp;&amp; index &lt; size)</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, arr[index]);</span></span></code></pre></div><h4 id="步骤-4-使用未初始化的变量" tabindex="-1">步骤 4. 使用未初始化的变量 <a class="header-anchor" href="#步骤-4-使用未初始化的变量" aria-label="Permalink to &quot;步骤 4. 使用未初始化的变量&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x);  // UB: x is uninitialized</span></span></code></pre></div><p>即使打印出来<code>0</code>，那是运气，而不是正确性。始终显式初始化变量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 0;</span></span></code></pre></div><h4 id="步骤-5-悬空指针" tabindex="-1">步骤 5. 悬空指针 <a class="header-anchor" href="#步骤-5-悬空指针" aria-label="Permalink to &quot;步骤 5. 悬空指针&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *p = malloc(sizeof(int));</span></span>
<span class="line"><span>*p = 10;</span></span>
<span class="line"><span>free(p);</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, *p);  // UB: accessing freed memory</span></span></code></pre></div><p>后<code>free()</code>，指针仍然存在，但内存不属于你。将其设置为<code>NULL</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>free(p);</span></span>
<span class="line"><span>p = NULL;</span></span></code></pre></div><h4 id="步骤-6-有符号整数溢出" tabindex="-1">步骤 6. 有符号整数溢出 <a class="header-anchor" href="#步骤-6-有符号整数溢出" aria-label="Permalink to &quot;步骤 6. 有符号整数溢出&quot;">​</a></h4><p>在 C 中，有符号溢出是未定义的，但无符号溢出可以预见地回绕。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 2147483647;</span></span>
<span class="line"><span>x = x + 1;  // UB</span></span></code></pre></div><p>未签名版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unsigned int x = 4294967295;</span></span>
<span class="line"><span>x = x + 1;  // wraps to 0 (defined)</span></span></code></pre></div><p>要安全地检查溢出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (a &gt; INT_MAX - b) {</span></span>
<span class="line"><span>    printf(&quot;overflow\\n&quot;);</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>    x = a + b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="步骤-7-在一个表达式中修改和读取" tabindex="-1">步骤 7. 在一个表达式中修改和读取 <a class="header-anchor" href="#步骤-7-在一个表达式中修改和读取" aria-label="Permalink to &quot;步骤 7. 在一个表达式中修改和读取&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int i = 0;</span></span>
<span class="line"><span>i = i++ + 1;  // UB: reading and writing i without sequence point</span></span></code></pre></div><p>避免同时出现副作用。编写干净的代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>i++;</span></span>
<span class="line"><span>i = i + 1;</span></span></code></pre></div><h4 id="步骤-8-空指针取消引用" tabindex="-1">步骤 8. 空指针取消引用 <a class="header-anchor" href="#步骤-8-空指针取消引用" aria-label="Permalink to &quot;步骤 8. 空指针取消引用&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *p = NULL;</span></span>
<span class="line"><span>*p = 10;</span><span>  // UB</span></span></code></pre></div><p>始终验证指针：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (p != NULL) *p = 10;</span></span></code></pre></div><h4 id="步骤-9-类型双关和别名" tabindex="-1">步骤 9. 类型双关和别名 <a class="header-anchor" href="#步骤-9-类型双关和别名" aria-label="Permalink to &quot;步骤 9. 类型双关和别名&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>float f = 3.14;</span></span>
<span class="line"><span>int *ip = (int *)&amp;f;  // UB: violates strict aliasing</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, *ip);</span></span></code></pre></div><p>如果必须重新解释字节，请使用<code>memcpy</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int i;</span></span>
<span class="line"><span>memcpy(&amp;i, &amp;f, sizeof(i));</span></span></code></pre></div><p>这可以避免别名冲突并且跨编译器是安全的。</p><h4 id="步骤10-tiny-code-使用工具检测ub" tabindex="-1">步骤10.Tiny Code：使用工具检测UB <a class="header-anchor" href="#步骤10-tiny-code-使用工具检测ub" aria-label="Permalink to &quot;步骤10.Tiny Code：使用工具检测UB&quot;">​</a></h4><p>使用编译器和运行时检查器在 UB 投入生产之前对其进行检测。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -fsanitize=undefined -g ub_example.c -o ub_example</span></span>
<span class="line"><span>./ub_example</span></span></code></pre></div><p>示例程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x = 2147483647;</span></span>
<span class="line"><span>    x++;</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>runtime error: signed integer overflow: 2147483647 + 1 cannot be represented in type &#39;int&#39;</span></span></code></pre></div><p>这是运行中的未定义行为清理程序 (UBSan)，它是您查找隐形错误的最佳朋友。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>未定义的行为是无声的腐败。它可以：</p><ul><li>在你的机器上工作但在其他地方失败。</li><li>更改编译器标志时中断。</li><li>造成微妙的、不可预测的错误。</li></ul><p>避免 UB 是可靠系统编程的基础。在C语言中，正确性来自于纪律。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个带有故意UB的小程序（例如使用未初始化的变量）。</li><li>运行它<code>-fsanitize=undefined</code>.</li><li>修复每个问题，直到 UBSan 运行干净。</li><li>检查数组访问和指针的有效性。 5.重构旧的C代码以避免UB，这是一个很好的调试练习。</li></ol><p>接下来，您将学习如何执行崩溃分析和读取核心转储，因此即使您的程序失败，您也可以找出确切的原因。</p>`,61)])])}const g=s(i,[["render",p]]);export{u as __pageData,g as default};
